  "Popover": "'use client';\n\nimport React from 'react';\nimport { Button, Popover, QRCode } from '@ceebee/ui/client';\n\nconst App: React.FC = () => (\n  <Popover content={<QRCode value=\"https://ceebee.dev\" bordered={false} />}>\n    <Button type=\"primary\">Hover me</Button>\n  </Popover>\n);\n\nexport default App;\n",
  "base": "'use client';\n\nimport React from 'react';\nimport { Input, QRCode, Space } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [text, setText] = React.useState('https://ceebee.dev/');\n\n  return (\n    <Space vertical align=\"center\">\n      <QRCode value={text || '-'} />\n      <Input\n        placeholder=\"-\"\n        maxLength={60}\n        value={text}\n        onChange={(e) => setText(e.target.value)}\n      />\n    </Space>\n  );\n};\n\nexport default App;\n",
  "customColor": "'use client';\n\nimport React from 'react';\nimport { QRCode, Space, theme } from '@ceebee/ui/client';\n\nconst { useToken } = theme;\n\nconst App: React.FC = () => {\n  const { token } = useToken();\n  return (\n    <Space>\n      <QRCode value=\"https://ceebee.dev/\" color={token.colorSuccessText} />\n      <QRCode\n        value=\"https://ceebee.dev/\"\n        color={token.colorInfoText}\n        bgColor={token.colorBgLayout}\n      />\n    </Space>\n  );\n};\n\nexport default App;\n",
  "customSize": "'use client';\n\nimport React, { useState } from 'react';\nimport { MinusOutlined, PlusOutlined } from '@ant-design/icons';\nimport { Button, QRCode, Space } from '@ceebee/ui/client';\n\nconst MIN_SIZE = 48;\nconst MAX_SIZE = 300;\n\nconst App: React.FC = () => {\n  const [size, setSize] = useState<number>(160);\n\n  const increase = () => {\n    setSize((prevSize) => {\n      const newSize = prevSize + 10;\n      if (newSize >= MAX_SIZE) {\n        return MAX_SIZE;\n      }\n      return newSize;\n    });\n  };\n\n  const decline = () => {\n    setSize((prevSize) => {\n      const newSize = prevSize - 10;\n      if (newSize <= MIN_SIZE) {\n        return MIN_SIZE;\n      }\n      return newSize;\n    });\n  };\n\n  return (\n    <>\n      <Space.Compact style={{ marginBottom: 16 }}>\n        <Button onClick={decline} disabled={size <= MIN_SIZE} icon={<MinusOutlined />}>\n          Smaller\n        </Button>\n        <Button onClick={increase} disabled={size >= MAX_SIZE} icon={<PlusOutlined />}>\n          Larger\n        </Button>\n      </Space.Compact>\n      <QRCode\n        errorLevel=\"H\"\n        size={size}\n        iconSize={size / 4}\n        value=\"https://ceebee.dev/\"\n        icon=\"https://gw.alipayobjects.com/zos/rmsportal/KDpgvguMpGfqaHPjicRK.svg\"\n      />\n    </>\n  );\n};\n\nexport default App;\n",
  "customStatusRender": "'use client';\n\nimport React from 'react';\nimport { CheckCircleFilled, CloseCircleFilled, ReloadOutlined } from '@ant-design/icons';\nimport type { QRCodeProps } from '@ceebee/ui/client';\nimport { Button, Flex, QRCode, Space, Spin } from '@ceebee/ui/client';\n\nconst value = 'https://ceebee.dev';\n\nconst customStatusRender: QRCodeProps['statusRender'] = (info) => {\n  switch (info.status) {\n    case 'expired':\n      return (\n        <div>\n          <CloseCircleFilled style={{ color: 'red' }} /> {info.locale?.expired}\n          <p>\n            <Button type=\"link\" onClick={info.onRefresh}>\n              <ReloadOutlined /> {info.locale?.refresh}\n            </Button>\n          </p>\n        </div>\n      );\n    case 'loading':\n      return (\n        <Space vertical>\n          <Spin />\n          <p>Loading...</p>\n        </Space>\n      );\n    case 'scanned':\n      return (\n        <div>\n          <CheckCircleFilled style={{ color: 'green' }} /> {info.locale?.scanned}\n        </div>\n      );\n    default:\n      return null;\n  }\n};\n\nconst App: React.FC = () => (\n  <Flex gap=\"medium\" wrap>\n    <QRCode value={value} status=\"loading\" statusRender={customStatusRender} />\n    <QRCode\n      value={value}\n      status=\"expired\"\n      onRefresh={() => console.log('refresh')}\n      statusRender={customStatusRender}\n    />\n    <QRCode value={value} status=\"scanned\" statusRender={customStatusRender} />\n  </Flex>\n);\n\nexport default App;\n",
  "download": "'use client';\n\nimport React from 'react';\nimport { Button, QRCode, Segmented, Space } from '@ceebee/ui/client';\nimport type { QRCodeProps } from '@ceebee/ui/client';\n\nfunction doDownload(url: string, fileName: string) {\n  const a = document.createElement('a');\n  a.download = fileName;\n  a.href = url;\n  document.body.appendChild(a);\n  a.click();\n  document.body.removeChild(a);\n}\n\nconst downloadCanvasQRCode = () => {\n  const canvas = document.getElementById('myqrcode')?.querySelector<HTMLCanvasElement>('canvas');\n  if (canvas) {\n    const url = canvas.toDataURL();\n    doDownload(url, 'QRCode.png');\n  }\n};\n\nconst downloadSvgQRCode = () => {\n  const svg = document.getElementById('myqrcode')?.querySelector<SVGElement>('svg');\n  const svgData = new XMLSerializer().serializeToString(svg!);\n  const blob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });\n  const url = URL.createObjectURL(blob);\n\n  doDownload(url, 'QRCode.svg');\n};\n\nconst App: React.FC = () => {\n  const [renderType, setRenderType] = React.useState<QRCodeProps['type']>('canvas');\n  return (\n    <Space id=\"myqrcode\" vertical>\n      <Segmented options={['canvas', 'svg']} value={renderType} onChange={setRenderType} />\n      <div>\n        <QRCode\n          type={renderType}\n          value=\"https://ceebee.dev/\"\n          bgColor=\"rgba(255,255,255,0.5)\"\n          style={{ marginBottom: 16 }}\n          icon=\"https://gw.alipayobjects.com/zos/rmsportal/KDpgvguMpGfqaHPjicRK.svg\"\n        />\n        <Button\n          type=\"primary\"\n          onClick={renderType === 'canvas' ? downloadCanvasQRCode : downloadSvgQRCode}\n        >\n          Download\n        </Button>\n      </div>\n    </Space>\n  );\n};\n\nexport default App;\n",
  "errorlevel": "'use client';\n\nimport React, { useState } from 'react';\nimport type { QRCodeProps } from '@ceebee/ui/client';\nimport { QRCode, Segmented } from '@ceebee/ui/client';\n\nconst App: React.FC = () => {\n  const [level, setLevel] = useState<QRCodeProps['errorLevel']>('L');\n  return (\n    <>\n      <QRCode\n        style={{ marginBottom: 16 }}\n        errorLevel={level}\n        value=\"https://gw.alipayobjects.com/zos/rmsportal/KDpgvguMpGfqaHPjicRK.svg\"\n      />\n      <Segmented options={['L', 'M', 'Q', 'H']} value={level} onChange={setLevel} />\n    </>\n  );\n};\n\nexport default App;\n",
