  "style-class": "'use client';\n\nimport React from 'react';\nimport { Flex, QRCode } from '@ceebee/ui/client';\nimport type { GetProp, QRCodeProps } from '@ceebee/ui/client';\nimport { createStaticStyles } from 'antd-style';\n\nconst classNames = createStaticStyles(({ css }) => ({\n  root: css`\n    border: 1px solid #ccc;\n    border-radius: 8px;\n    padding: 16px;\n  `,\n}));\n\nconst stylesObject: QRCodeProps['styles'] = {\n  root: {\n    border: '2px solid #1890ff',\n    borderRadius: 8,\n    padding: 16,\n    backgroundColor: 'rgb(24, 144, 255, 0.1)',\n  },\n};\n\nconst stylesFunction: QRCodeProps['styles'] = (info): GetProp<QRCodeProps, 'styles', 'Return'> => {\n  if (info.props.type === 'canvas') {\n    return {\n      root: {\n        border: '2px solid #ff4d4f',\n        borderRadius: 8,\n        padding: 16,\n        backgroundColor: 'rgba(255, 77, 79, 0.1)',\n      },\n    };\n  }\n};\n\nconst App: React.FC = () => {\n  const sharedProps: QRCodeProps = {\n    value: 'https://ceebee.dev/',\n    size: 160,\n    classNames,\n  };\n\n  return (\n    <Flex gap=\"medium\">\n      <QRCode {...sharedProps} styles={stylesObject} />\n      <QRCode\n        {...sharedProps}\n        type=\"canvas\"\n        icon=\"https://gw.alipayobjects.com/zos/rmsportal/KDpgvguMpGfqaHPjicRK.svg\"\n        styles={stylesFunction}\n      />\n    </Flex>\n  );\n};\n\nexport default App;\n",
